function chart(id,lines,labels,format,threshold=null){const el=$(id),W=1000,H=280,L=80,R=975,T=24,B=235;el.setAttribute('viewBox',`0 0 ${W} ${H}`);const vv=lines.flatMap(s=>s.values.filter(Number.isFinite));if(!vv.length){el.innerHTML='<text x="30" y="80">No complete series available.</text>';return}const max=Math.max(...vv,threshold||0)*1.12,min=Math.min(0,...vv),x=i=>L+i*(R-L)/Math.max(1,labels.length-1),y=v=>B-(v-min)/(max-min||1)*(B-T);let s='';for(let j=0;j<5;j++){let v=min+(max-min)*j/4;s+=`<line x1="${L}" x2="${R}" y1="${y(v)}" y2="${y(v)}" stroke="#e3e9e3"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#74827b">${format(v)}</text>`}if(threshold!=null)s+=`<line x1="${L}" x2="${R}" y1="${y(threshold)}" y2="${y(threshold)}" stroke="#74827b" stroke-dasharray="4 5"/>`;lines.forEach(a=>{let path='',segment=[];a.values.forEach((v,i)=>{if(Number.isFinite(v))segment.push([x(i),y(v)]);else{path+=window.NearCurves.path(segment);segment=[]}});path+=window.NearCurves.path(segment);s+=`<path d="${path}" fill="none" stroke="${a.color}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>`;a.values.forEach((v,i)=>{if(Number.isFinite(v))s+=`<circle cx="${x(i)}" cy="${y(v)}" r="5" opacity="0" fill="${a.color}" onpointerenter="this.setAttribute('opacity','1')" onpointerleave="this.setAttribute('opacity','0')" onfocus="this.setAttribute('opacity','1')" onblur="this.setAttribute('opacity','0')"><title>${labels[i]} · ${a.name}: ${format(v)}</title></circle>`})});labels.forEach((v,i)=>{if(labels.length<12||i%Math.ceil(labels.length/7)===0||i===labels.length-1)s+=`<text x="${x(i)}" y="265" text-anchor="middle" font-size="11" fill="#74827b">${v}</text>`});el.innerHTML=s;}
function render(){const m=D.months[selected],growth=m.growth||{};$('flowPeriod').textContent=label(m.month)+(m.complete?'':' · so far');$('cards').innerHTML=['volume','fees','revenue','buy'].map(k=>`<div class="card"><div class="label">${k==='buy'?'Buyback wallet inflows':names[k]}</div><div class="value">${k==='buy'?fmt(m[k]):usd(m[k])}</div><div class="delta ${growth[k]<0?'negative':''}">${signed(growth[k])} ${m.complete?'vs previous month':'vs matching days'}</div></div>`).join('');$('quality').textContent=m.notes.filter(x=>!x.includes('retained')).join(' ')||'Complete daily records are present. Source-level activity has not been audited trade by trade.';$('pipeline').innerHTML=[['Swap volume',usd(m.volume),'Activity processed'],['Swap fees',usd(m.fees),pct(m.feeRate,3)+' of volume'],['Captured revenue',usd(m.revenue),pct(m.captureRate)+' of fees'],['NEAR received',fmt(m.buy)+' NEAR',m.mint?pct(m.buy/m.mint)+' of issuance':'Current issuance unavailable']].map((x,i)=>`<div class="step"><small>${i+1} · ${x[0]}</small><strong>${x[1]}</strong><div class="flowrate">${x[2]}</div></div>`).join('');$('flowNote').textContent='Collections and wallet arrivals can lag the underlying swaps. '+(m.buyUsdEstimate!=null?`Arrival-date valuation of wallet inflows: ${usd(m.buyUsdEstimate)}; quantity-weighted market-price estimate ${usd(m.buyPriceEstimate)} per NEAR. This is not verified purchase expenditure, so it is not used to infer a revenue-spending allocation.`:'No arrival-date valuation loaded for this month.');drawGrowth();}
