function history(){ $('historyRows').innerHTML=D.months.map(m=>`<tr><td>${label(m.month)}${m.complete?'':' <span class="pill">1–'+m.days+' only</span>'}</td>${['volume','fees','revenue','buy'].map(k=>`<td>${k==='buy'?fmt(m[k]):usd(m[k])}<br><small class="${m.growth?.[k]<0?'negative':''}">${signed(m.growth?.[k])}</small></td>`).join('')}<td>${pct(m.feeRate,3)}</td><td>${pct(m.captureRate)}</td><td>${m.mint&&m.buy!=null?pct(m.buy/m.mint):'Unavailable'}</td></tr>`).join('');}
