function market(){let rows=D.daily.filter(r=>['near','btc','eth'].every(k=>r[k]!=null));const n=$('marketWindow').value;if(n!=='all')rows=rows.slice(-Number(n));if(rows.length<2){$('marketSummary').textContent='Price history unavailable.';return}chart('marketChart',['near','btc','eth'].map((k,i)=>({name:k.toUpperCase(),color:['#248365','#d48a43','#456bed'][i],values:rows.map(r=>r[k]/rows[0][k]*100)})),rows.map(r=>r.date.slice(5)),n=>fmt(n));const first=rows[0],last=rows.at(-1),ret=k=>last[k]/first[k]-1,a=[],b=[];for(let i=1;i<rows.length;i++){a.push(rows[i].near/rows[i-1].near-1);b.push(rows[i].btc/rows[i-1].btc-1)}const co=corr(a,b);$('marketSummary').textContent=`${first.date} → ${last.date}: NEAR ${signed(ret('near'))}; BTC ${signed(ret('btc'))}; ETH ${signed(ret('eth'))}. NEAR minus BTC return: ${((ret('near')-ret('btc'))*100).toFixed(1)} percentage points. Daily NEAR–BTC return correlation: ${co==null?'unavailable':co.toFixed(2)} (${a.length} paired returns).`;
const pairs=D.months.filter(m=>m.complete&&m.growth?.volume!=null).map(m=>{const r=D.daily.filter(r=>r.date.startsWith(m.month)&&r.near&&r.btc),next=D.daily.find(r=>r.date===nextMonth(m.month)+'-01');if(!r.length||!next?.near||!next?.btc)return null;return {month:m.month,vg:m.growth.volume,nr:next.near/r[0].near-1,br:next.btc/r[0].btc-1};}).filter(Boolean);const c=corr(pairs.map(x=>x.vg),pairs.map(x=>x.nr));$('activityAssociation').innerHTML=`<p>Volume-growth / NEAR-return correlation: <b>${c==null?'Unavailable':c.toFixed(2)}</b>, based on only ${pairs.length} complete monthly pairs. Too short to establish a stable relationship.</p><div class="tablewrap"><table><thead><tr><th>Month</th><th>Volume growth</th><th>NEAR return</th><th>BTC return</th></tr></thead><tbody>${pairs.map(x=>`<tr><td>${label(x.month)}</td><td>${signed(x.vg)}</td><td>${signed(x.nr)}</td><td>${signed(x.br)}</td></tr>`).join('')}</tbody></table></div>`;}
